style.css:
@-moz-document domain("youtube.com") {
/* 1. CUSTOM WALLPAPER CONFIGURATION */
    body, ytd-app {
        background-image: url("https://wallpapercave.com/igari-desktop-wallpapers") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
    }

    /* Make background transparent so your wallpaper shows */
    #page-manager, ytd-browse, ytd-watch-flexy, #content {
        background: transparent !important;
    }

    /* Translucent dark tint for top bar and sidebar readability */
    #masthead-container, #contentContainer, #guide-content, #chat-container, ytd-playlist-panel-renderer {
        background: rgba(15, 15, 15, 0.75) !important;
        backdrop-filter: blur(10px) !important;
    }

    /* 2. CUSTOM LOGO CONFIGURATION */
    /* Hide the default YouTube vector graphics */
    ytd-logo svg g, 
    ytd-logo .yt-icon-shape,
    #country-code {
        display: none !important;
    }

    /* Insert your custom logo graphic */
    ytd-logo svg {
        background-image: url("https://ar.pinterest.com/pin/627830004345204548/") !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: left center !important;
        width: 100px !important;  /* Tweak width as needed */
        height: 30px !important;  /* Tweak height as needed */
    }
}
